const VIEWBOX = { width: 720, height: 1280 };

const AnimatedPath = Animated.createAnimatedComponent(Path);

export const OnboardingAnimation: React.FC<OnboardingAnimationProps> = ({
  frameDuration = FRAME_DURATION,
  loop = false,
  onComplete,
  resizeMode = 'contain',
  style,
  brandColor = '#5B21B6',
}) => {
  const frameIndex = useSharedValue(0);
  const isPlaying = useSharedValue(true);

  // Reanimated 4: completion callback lives on the last inner animation.
  const animate = useCallback(() => {
    if (!isPlaying.value) return;
    frameIndex.value = withSequence(
      withTiming(1, { duration: frameDuration }),
      withTiming(2, { duration: frameDuration }, (finished) => {
        if (!finished) return;
        if (loop) {
          frameIndex.value = withDelay(0, withTiming(0, { duration: 0 }));
          runOnJS(animate)();
        } else {
          isPlaying.value = false;
          if (onComplete) runOnJS(onComplete)();
        }
      })
    );
  }, [frameDuration, loop, onComplete]);

  useEffect(() => {
    isPlaying.value = true;
    frameIndex.value = 0;
    animate();
    return () => { isPlaying.value = false; };
  }, [animate]);

  // Crossfade both morph frames off the continuous frameIndex value:
  // frame 1 (hexagon) fades in over the first tween and out at the boundary;
  // frame 2 (lockup) fades in across the boundary and holds to the end.
  const hexagonProps = useAnimatedProps(() => ({
    fillOpacity: interpolate(frameIndex.value, [0, 0.85, 1, 1.15], [0, 1, 1, 0], Extrapolation.CLAMP),
  }));
  const lockupProps = useAnimatedProps(() => ({
    fillOpacity: interpolate(frameIndex.value, [0.85, 1.15, 2], [0, 1, 1], Extrapolation.CLAMP),
  }));

  const animatedStyle = useAnimatedStyle(() => ({ opacity: 1 }));

  void resizeMode;

  return (
    <View style={[styles.container, style]}>
      <Animated.View style={[styles.svgWrapper, animatedStyle]}>
        <Svg viewBox={`0 0 ${VIEWBOX.width} ${VIEWBOX.height}`} style={styles.svg}>
          <AnimatedPath d={FRAME_PATHS[0]} fill={brandColor} fillOpacity={0} />
          <AnimatedPath d={FRAME_PATHS[1]} fill={brandColor} animatedProps={hexagonProps} />
          <AnimatedPath d={FRAME_PATHS[2]} fill={brandColor} animatedProps={lockupProps} />
        </Svg>
      </Animated.View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
  },
  svgWrapper: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
  },
  svg: {
    width: '100%',
    height: '100%',
  },
});

export default OnboardingAnimation;